/// Binary search lookup on the sorted dispatch table.
/// Returns nullptr if fnv24 not found (fallback to resolve_type_arg +
/// chaos_find_enum_metadata).
inline static const EnumMetadataTable* chaos_dispatch_lookup(
    CHAOS_IL2CPP_UINT32 fnv24) noexcept
{
    CHAOS_IL2CPP_UINT32 lo = 0u, hi = kEnumDispatchCount;
    while (lo < hi) {
        CHAOS_IL2CPP_UINT32 mid = lo + (hi - lo) / 2u;
        if (kEnumDispatchTable[mid].fnv24 < fnv24)
            lo = mid + 1u;
        else if (kEnumDispatchTable[mid].fnv24 > fnv24)
            hi = mid;
        else
            return kEnumDispatchTable[mid].table;
    }
    return nullptr;
}

/// Lookup enum metadata by subject_id FNV-1a 32-bit hash via dispatch table binary search.
/// Returns nullptr if the type is unknown (fallback to reflection API).
inline static const EnumMetadataTable* chaos_find_enum_metadata(
    const char* subject_id) noexcept
{
    if (subject_id == nullptr || subject_id[0] == '\0')
        return nullptr;
    return chaos_dispatch_lookup(compute_enum_hash32(subject_id) & 0xFFFFFFu);
}


